// icons.mjs — task 015: app icon assets for iPhone home-screen install.
//
// PNGs are base64-embedded so this module imports identically in node
// tests and in the esbuild worker bundle (no fs, no build step) — the
// same pattern as the dashboard literals in dashboard.mjs. Source art:
// hub/assets/ai-hub-icon-bubbles-opaque.png (David-approved chat-bubbles concept).

export const ICONS = {
  'apple-touch-icon': { contentType: 'image/png', base64: '' },
  'icon-192': { contentType: 'image/png', base64: '' },
  'icon-512': { contentType: 'image/png', base64: '' },
  'icon-maskable-512': { contentType: 'image/png', base64: '' },
  'favicon': { contentType: 'image/png', base64: '' },
};

export const MANIFEST_JSON = {
  "name": "AI Coordination Hub",
  "short_name": "AI Hub",
  "start_url": "/dashboard",
  "display": "standalone",
  "background_color": "#0f1420",
  "theme_color": "#0f1420",
  "icons": [
    {
      "src": "/dashboard/icons/icon-192.png",
      "sizes": "192x192",
      "type": "image/png"
    },
    {
      "src": "/dashboard/icons/icon-512.png",
      "sizes": "512x512",
      "type": "image/png"
    },
    {
      "src": "/dashboard/icons/icon-maskable-512.png",
      "sizes": "512x512",
      "type": "image/png",
      "purpose": "maskable"
    }
  ]
};

// atob is available in Workers and in Node >= 16.
export function iconBytes(name) {
  const e = ICONS[name];
  if (!e) return null;
  const bin = atob(e.base64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return { contentType: e.contentType, bytes: out };
}
